import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {mkdtempSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {planRedactions} from '../redaction-plan.js';

const CLI = fileURLToPath(new URL('../redaction-plan.js', import.meta.url));

function runCli(args) {
  return spawnSync(process.execPath, [CLI, ...args], {encoding: 'utf8'});
}

let tmp = null;
test.before(() => {
  tmp = mkdtempSync(path.join(tmpdir(), 'redaction-plan-'));
});
test.after(() => {
  if (tmp) rmSync(tmp, {recursive: true, force: true});
});
function writeInput(name, content) {
  const file = path.join(tmp, name);
  writeFileSync(file, content, 'utf8');
  return file;
}

// --- spec example and result shape ---

test('spec example: overlapping literals select long-then-touching-short', () => {
  assert.deepEqual(
    planRedactions('ababa', [
      {id: 'long', literal: 'aba', replacement: 'X'},
      {id: 'short', literal: 'ba', replacement: 'Y'},
    ]),
    {
      text: 'XY',
      edits: [
        {start: 0, end: 3, id: 'long'},
        {start: 3, end: 5, id: 'short'},
      ],
      originalBytes: 5,
      redactedBytes: 2,
    }
  );
});

test('result is exactly {text, edits, originalBytes, redactedBytes}', () => {
  const result = planRedactions('no matches', []);
  assert.deepEqual(Object.keys(result).sort(), ['edits', 'originalBytes', 'redactedBytes', 'text']);
  assert.deepEqual(result, {text: 'no matches', edits: [], originalBytes: 10, redactedBytes: 10});
});

test('edits carry exactly {start, end, id} and are ordered by source position', () => {
  const result = planRedactions('bbab', [
    {id: 'x', literal: 'a', replacement: 'X'},
    {id: 'y', literal: 'bb', replacement: 'Y'},
  ]);
  // Rule "y" is second in the array but its match starts earlier.
  assert.deepEqual(result.edits, [
    {start: 0, end: 2, id: 'y'},
    {start: 2, end: 3, id: 'x'},
  ]);
  assert.equal(result.text, 'YXb');
});

// --- matching semantics ---

test('overlapping occurrences of a single literal are all considered', () => {
  const result = planRedactions('aaaa', [{id: 'aa', literal: 'aa', replacement: 'X'}]);
  // Candidates at 0, 1, 2; select (0,2) then (2,4); (1,3) rejected.
  assert.deepEqual(result.edits, [
    {start: 0, end: 2, id: 'aa'},
    {start: 2, end: 4, id: 'aa'},
  ]);
  assert.equal(result.text, 'XX');
});

test('same start: longest literal wins; touching edits are allowed', () => {
  const result = planRedactions('abcab', [
    {id: 's', literal: 'ab', replacement: 'S'},
    {id: 'l', literal: 'abc', replacement: 'L'},
  ]);
  assert.deepEqual(result.edits, [
    {start: 0, end: 3, id: 'l'},
    {start: 3, end: 5, id: 's'},
  ]);
  assert.equal(result.text, 'LS');
});

test('equal length at same start: earlier rule-array position wins', () => {
  const result = planRedactions('ab', [
    {id: 'first', literal: 'ab', replacement: 'F'},
    {id: 'second', literal: 'ab', replacement: 'S'},
  ]);
  assert.deepEqual(result.edits, [{start: 0, end: 2, id: 'first'}]);
  assert.equal(result.text, 'F');
});

test('matches are case-sensitive exact literals, not regular expressions', () => {
  assert.equal(planRedactions('Abc', [{id: 'c', literal: 'abc', replacement: 'X'}]).text, 'Abc');
  assert.equal(planRedactions('abc', [{id: 'd', literal: 'a.c', replacement: 'X'}]).text, 'abc');
  assert.equal(planRedactions('abc', [{id: 'd', literal: '.', replacement: 'X'}]).text, 'abc');
});

test('replacement text is never reprocessed', () => {
  assert.deepEqual(planRedactions('a', [{id: 'a', literal: 'a', replacement: 'aa'}]), {
    text: 'aa',
    edits: [{start: 0, end: 1, id: 'a'}],
    originalBytes: 1,
    redactedBytes: 2,
  });
  const r = planRedactions('ab', [{id: 'a', literal: 'a', replacement: 'ab'}]);
  assert.equal(r.text, 'abb');
  assert.deepEqual(r.edits, [{start: 0, end: 1, id: 'a'}]);
});

test('empty replacement removes the literal and preserves the rest', () => {
  assert.deepEqual(planRedactions('abc', [{id: 'b', literal: 'b', replacement: ''}]), {
    text: 'ac',
    edits: [{start: 1, end: 2, id: 'b'}],
    originalBytes: 3,
    redactedBytes: 2,
  });
});

test('offsets are UTF-16 code units, not UTF-8 bytes', () => {
  const smiley = '\u{1F600}'; // 2 UTF-16 code units, 4 UTF-8 bytes
  const result = planRedactions('x' + smiley + 'y', [{id: 'sm', literal: smiley, replacement: 'X'}]);
  assert.deepEqual(result.edits, [{start: 1, end: 3, id: 'sm'}]);
  assert.equal(result.text, 'xXy');
  assert.equal(result.originalBytes, 6);
  assert.equal(result.redactedBytes, 3);

  const latin = planRedactions('éx', [{id: 'e', literal: 'é', replacement: 'X'}]);
  assert.deepEqual(latin.edits, [{start: 0, end: 1, id: 'e'}]);
  assert.equal(latin.text, 'Xx');
  assert.equal(latin.originalBytes, 3);
  assert.equal(latin.redactedBytes, 2);
});

test('byte counts use utf8 for replacements too', () => {
  const result = planRedactions('a', [{id: 'a', literal: 'a', replacement: 'éé'}]);
  assert.equal(result.text, 'éé');
  assert.equal(result.originalBytes, 1);
  assert.equal(result.redactedBytes, 4);
});

test('empty text with valid rules yields empty result', () => {
  assert.deepEqual(planRedactions('', []), {text: '', edits: [], originalBytes: 0, redactedBytes: 0});
  assert.deepEqual(
    planRedactions('', [{id: 'a', literal: 'a', replacement: 'x'}]),
    {text: '', edits: [], originalBytes: 0, redactedBytes: 0}
  );
});

test('extra rule fields are ignored; opaque ids like __proto__ work', () => {
  const withExtras = planRedactions('ab', [{id: 'a', literal: 'ab', replacement: 'X', note: 'ignored', n: 1}]);
  assert.equal(withExtras.text, 'X');
  const proto = planRedactions('a', [{id: '__proto__', literal: 'a', replacement: 'Z'}]);
  assert.deepEqual(proto.edits, [{start: 0, end: 1, id: '__proto__'}]);
  assert.equal(proto.text, 'Z');
  assert.equal(Object.prototype.a, undefined); // no accidental pollution
});

// --- input handling guarantees ---

test('frozen inputs work and inputs are not mutated', () => {
  const rules = Object.freeze([Object.freeze({id: 'a', literal: 'ab', replacement: 'X'})]);
  assert.deepEqual(planRedactions('ab', rules), {
    text: 'X',
    edits: [{start: 0, end: 2, id: 'a'}],
    originalBytes: 2,
    redactedBytes: 1,
  });
  const mutable = [{id: 'a', literal: 'ab', replacement: 'X'}];
  const snapshot = JSON.parse(JSON.stringify(mutable));
  planRedactions('ab', mutable);
  assert.deepEqual(mutable, snapshot);
});

test('invalid inputs throw an Error', () => {
  const okRule = (i) => ({id: 'r' + i, literal: 'a', replacement: ''});
  const bad = [
    [42, []],
    [null, []],
    [{}, []],
    [new String('ab'), []],
    ['ab', null],
    ['ab', undefined],
    ['ab', 'nope'],
    ['ab', {rules: []}],
    ['ab', {length: 0}],
    ['ab', [null]],
    ['ab', [42]],
    ['ab', ['str']],
    ['ab', [[{id: 'a', literal: 'a', replacement: ''}]]],
    ['ab', [() => {}]],
    ['ab', [{}]],
    ['ab', [{id: '', literal: 'a', replacement: ''}]],
    ['ab', [{id: 1, literal: 'a', replacement: ''}]],
    ['ab', [{id: null, literal: 'a', replacement: ''}]],
    ['ab', [{literal: 'a', replacement: ''}]],
    ['ab', [{id: 'a', literal: '', replacement: ''}]],
    ['ab', [{id: 'a', literal: 5, replacement: ''}]],
    ['ab', [{id: 'a', replacement: ''}]],
    ['ab', [{id: 'a', literal: 'a'}]],
    ['ab', [{id: 'a', literal: 'a', replacement: 0}]],
    ['ab', [{id: 'a', literal: 'a', replacement: null}]],
    ['ab', [okRule(0), okRule(0)]], // duplicate id
    ['ab', [{id: 'r0', literal: 'a', replacement: ''}, {id: 'r0', literal: 'b', replacement: ''}]], // duplicate id
    ['ab', new Array(1)], // sparse (hole at 0)
  ];
  for (const [text, rules] of bad) {
    assert.throws(() => planRedactions(text, rules), Error, `expected throw for ${JSON.stringify(text)} / ${String(rules)}`);
  }
  // Validation runs before any matching, even when text is empty.
  assert.throws(() => planRedactions('', 'nope'), Error);
  assert.throws(() => planRedactions('', [{id: 'a', literal: 'a'}]), Error);
  assert.throws(() => planRedactions('', [{id: 'a', literal: 'a', replacement: ''}, {id: 'a', literal: 'b', replacement: ''}]), Error);
});

test('objects with null prototypes are accepted', () => {
  const rule = Object.assign(Object.create(null), {id: 'a', literal: 'ab', replacement: 'X'});
  assert.deepEqual(planRedactions('ab', [rule]).text, 'X');
});

// --- CLI ---

test('cli prints exactly the API result plus newline, exit 0, no stderr', () => {
  const file = writeInput(
    'ok.json',
    JSON.stringify({
      text: 'ababa',
      rules: [
        {id: 'long', literal: 'aba', replacement: 'X'},
        {id: 'short', literal: 'ba', replacement: 'Y'},
      ],
      extra: 'ignored',
    })
  );
  const r = runCli([file]);
  assert.equal(r.status, 0);
  assert.equal(r.stderr, '');
  const expected = {
    text: 'XY',
    edits: [
      {start: 0, end: 3, id: 'long'},
      {start: 3, end: 5, id: 'short'},
    ],
    originalBytes: 5,
    redactedBytes: 2,
  };
  assert.equal(r.stdout, JSON.stringify(expected) + '\n');
  assert.deepEqual(JSON.parse(r.stdout), expected);
});

test('cli handles multibyte output text', () => {
  const file = writeInput('mb.json', JSON.stringify({text: 'éx', rules: [{id: 'e', literal: 'é', replacement: 'X'}]}));
  const r = runCli([file]);
  assert.equal(r.status, 0);
  assert.equal(r.stderr, '');
  assert.equal(r.stdout, JSON.stringify({text: 'Xx', edits: [{start: 0, end: 1, id: 'e'}], originalBytes: 3, redactedBytes: 2}) + '\n');
});

test('cli accepts empty text and empty rules', () => {
  const file = writeInput('empty.json', JSON.stringify({text: '', rules: [], other: 1}));
  const r = runCli([file]);
  assert.equal(r.status, 0);
  assert.equal(r.stderr, '');
  assert.equal(r.stdout, JSON.stringify({text: '', edits: [], originalBytes: 0, redactedBytes: 0}) + '\n');
});

test('cli exits 2 with empty stdout and nonempty stderr on invalid input', () => {
  const badJson = writeInput('bad.json', '{nope');
  const missing = path.join(tmp, 'does-not-exist.json');
  const nullJson = writeInput('null.json', 'null');
  const arrayJson = writeInput('array.json', '[]');
  const scalarJson = writeInput('scalar.json', '123');
  const dupIdJson = writeInput('dup.json', JSON.stringify({
    text: 'ab',
    rules: [
      {id: 'a', literal: 'a', replacement: ''},
      {id: 'a', literal: 'b', replacement: ''},
    ],
  }));
  const badTextJson = writeInput('badtext.json', JSON.stringify({text: 5, rules: []}));

  for (const args of [
    [], // no arguments
    [badJson], // invalid JSON
    [missing], // missing file
    [tmp], // a directory
    [nullJson], // JSON null
    [arrayJson], // JSON array
    [scalarJson], // JSON scalar
    [dupIdJson], // API rejects duplicate id
    [badTextJson], // API rejects non-string text
    [badJson, missing], // too many arguments
  ]) {
    const r = runCli(args);
    assert.equal(r.status, 2, `expected exit 2 for args=${JSON.stringify(args)} (stderr=${r.stderr})`);
    assert.equal(r.stdout, '', 'expected no stdout on failure');
    assert.ok(r.stderr.length > 0, 'expected nonempty stderr on failure');
  }
});

test('importing the module does not run the CLI', () => {
  const r = spawnSync(
    process.execPath,
    ['-e', `import(${JSON.stringify(pathToFileURL(CLI).href)}).then(m => { if (typeof m.planRedactions !== 'function') process.exit(1); }).catch(() => process.exit(1));`],
    {encoding: 'utf8'}
  );
  assert.equal(r.status, 0);
  assert.equal(r.stdout, '');
  assert.equal(r.stderr, '');
});

